   460|  // Truncate to 4096 chars (OpenAI limit; Gateway is similar)
   461|  const truncatedText = trimmedText.slice(0, 4096);
   462|  if (trimmedText.length > 4096) {
   463|    console.warn('[IVX TTS] Text truncated from', trimmedText.length, 'to 4096 chars');
   464|  }
